```rust
use std::collections::BTreeSet;

wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Only a digest that was actually published has delivered its items.
        // An unpublished digest leaves its items unmarked so the next run
        // considers them again.
        let mut recorded: u32 = 0;
        if published.published {
            // Deduplicate and skip empty ids so each item is written once.
            let ids: BTreeSet<&str> = published
                .considered
                .iter()
                .map(|s| s.as_str())
                .filter(|s| !s.is_empty())
                .collect();

            for id in &ids {
                // Ids are parser-computed digests, safe to use as store keys.
                state_rw::put(id, "seen");
            }
            recorded = u32::try_from(ids.len()).unwrap_or(u32::MAX);
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
